13	export class SlashCommandConflictHandler {
14	  private notifiedConflicts = new Set<string>();
15	
16	  constructor() {
17	    this.handleConflicts = this.handleConflicts.bind(this);
18	  }
19	
20	  start() {
21	    coreEvents.on(CoreEvent.SlashCommandConflicts, this.handleConflicts);
22	  }
23	
24	  stop() {
25	    coreEvents.off(CoreEvent.SlashCommandConflicts, this.handleConflicts);
26	  }
27	
28	  private handleConflicts(payload: SlashCommandConflictsPayload) {
29	    const newConflicts = payload.conflicts.filter((c) => {
30	      const key = `${c.name}:${c.loserExtensionName}`;
31	      if (this.notifiedConflicts.has(key)) {
32	        return false;
33	      }
34	      this.notifiedConflicts.add(key);
35	      return true;
36	    });
37	
38	    if (newConflicts.length > 0) {
39	      const conflictMessages = newConflicts
40	        .map((c) => {
41	          const winnerSource = c.winnerExtensionName
42	            ? `extension '${c.winnerExtensionName}'`
43	            : 'an existing command';
44	          return `- Command '/${c.name}' from extension '${c.loserExtensionName}' was renamed to '/${c.renamedTo}' because it conflicts with ${winnerSource}.`;
45	        })
46	        .join('\n');
47	
48	      coreEvents.emitFeedback(
49	        'info',
50	        `Command conflicts detected:\n${conflictMessages}`,
51	      );
52	    }
53	  }
54	}
