7	import { CommandKind, type SlashCommand } from '../ui/commands/types.js';
8	import type { CommandConflict } from './types.js';
9	
10	/**
11	 * Internal registry to track commands and conflicts during resolution.
12	 */
13	class CommandRegistry {
14	  readonly commandMap = new Map<string, SlashCommand>();
15	  readonly conflictsMap = new Map<string, CommandConflict>();
16	  readonly firstEncounters = new Map<string, SlashCommand>();
17	
18	  get finalCommands(): SlashCommand[] {
19	    return Array.from(this.commandMap.values());
20	  }
21	
22	  get conflicts(): CommandConflict[] {
23	    return Array.from(this.conflictsMap.values());
24	  }
25	}
26	
27	/**
28	 * Resolves name conflicts among slash commands.
29	 *
30	 * Rules:
31	 * 1. Built-in commands always keep the original name.
32	 * 2. All other types are prefixed with their source name (e.g. user.name).
33	 * 3. If multiple non-built-in commands conflict, all of them are renamed.
34	 */
35	export class SlashCommandResolver {
36	  /**
37	   * Orchestrates conflict resolution by applying renaming rules to ensures
38	   * every command has a unique name.
39	   */
40	  static resolve(allCommands: SlashCommand[]): {
41	    finalCommands: SlashCommand[];
42	    conflicts: CommandConflict[];
43	  } {
44	    const registry = new CommandRegistry();
45	
46	    for (const cmd of allCommands) {
47	      const originalName = cmd.name;
48	      let finalName = originalName;
49	
50	      const shouldAlwaysPrefix =
51	        cmd.kind === CommandKind.SKILL && !!cmd.extensionName;
52	
53	      if (shouldAlwaysPrefix) {
54	        finalName = this.getRenamedName(
55	          originalName,
56	          this.getPrefix(cmd),
57	          registry.commandMap,
58	          cmd.kind,
59	        );
60	      } else if (registry.firstEncounters.has(originalName)) {
61	        // We've already seen a command with this name, so resolve the conflict.
62	        finalName = this.handleConflict(cmd, registry);
63	      } else {
64	        // Track the first claimant to report them as the conflict reason later.
65	        registry.firstEncounters.set(originalName, cmd);
66	      }
67	
68	      // Store under final name, ensuring the command object reflects it.
69	      registry.commandMap.set(finalName, {
70	        ...cmd,
71	        name: finalName,
72	      });
73	    }
74	
75	    return {
76	      finalCommands: registry.finalCommands,
77	      conflicts: registry.conflicts,
78	    };
79	  }
80	
81	  /**
82	   * Resolves a name collision by deciding which command keeps the name and which is renamed.
83	   *
84	   * @param incoming The command currently being processed that has a name collision.
85	   * @param registry The internal state of the resolution process.
86	   * @returns The final name to be assigned to the `incoming` command.
87	   */
88	  private static handleConflict(
89	    incoming: SlashCommand,
90	    registry: CommandRegistry,
91	  ): string {
92	    const collidingName = incoming.name;
93	    const originalClaimant = registry.firstEncounters.get(collidingName)!;
94	
95	    // Incoming built-in takes priority. Prefix any existing owner.
96	    if (incoming.kind === CommandKind.BUILT_IN) {
97	      this.prefixExistingCommand(collidingName, incoming, registry);
98	      return collidingName;
99	    }
100	
101	    // Incoming non-built-in is renamed to its source-prefixed version.
102	    const renamedName = this.getRenamedName(
103	      incoming.name,
104	      this.getPrefix(incoming),
105	      registry.commandMap,
106	      incoming.kind,
107	    );
108	    this.trackConflict(
109	      registry.conflictsMap,
110	      collidingName,
111	      originalClaimant,
112	      incoming,
113	      renamedName,
114	    );
115	
116	    // Prefix current owner as well if it isn't a built-in.
117	    this.prefixExistingCommand(collidingName, incoming, registry);
118	
119	    return renamedName;
120	  }
121	
122	  /**
123	   * Safely renames the command currently occupying a name in the registry.
124	   *
125	   * @param name The name of the command to prefix.
126	   * @param reason The incoming command that is causing the prefixing.
127	   * @param registry The internal state of the resolution process.
128	   */
129	  private static prefixExistingCommand(
130	    name: string,
131	    reason: SlashCommand,
132	    registry: CommandRegistry,
133	  ): void {
134	    const currentOwner = registry.commandMap.get(name);
135	
136	    // Only non-built-in commands can be prefixed.
137	    if (!currentOwner || currentOwner.kind === CommandKind.BUILT_IN) {
138	      return;
139	    }
140	
141	    // Determine the new name for the owner using its source prefix.
142	    const renamedName = this.getRenamedName(
143	      currentOwner.name,
